<?php /** 출퇴근 시스템: 출근 처리 */
use App\Core\Db; require_once __DIR__.'/common.php'; if(!\App\Core\Auth::check()){header('Location: ?r=login');exit;} if($_SERVER['REQUEST_METHOD']!=='POST'||!csrf_check(isset($_POST['_csrf'])?$_POST['_csrf']:'')){flash_set('danger','잘못된 요청입니다.');header('Location: ?r=대시보드');exit;} $pdo=Db::pdo(); $eid=attendance_employee_id($pdo); $today=attendance_today(); error_log('[attendance_check_in] employee_id='.$eid.' today='.$today); if($eid<=0||!$pdo){flash_set('danger','직원 정보를 찾을 수 없습니다.');header('Location: ?r=대시보드');exit;} try{$pdo->beginTransaction();$st=$pdo->prepare("SELECT * FROM cpms_attendance_records WHERE employee_id=:e AND work_date=:d LIMIT 1 FOR UPDATE");$st->execute(array(':e'=>$eid,':d'=>$today));$r=$st->fetch();$now=attendance_now(); if($r&&!attendance_record_datetime_matches_work_date($r)){throw new Exception('오늘 날짜에 잘못된 출퇴근 기록이 있습니다. 관리자에게 날짜 불일치 기록 복구를 요청해주세요.');} if($r&&$r['check_in']){throw new Exception('오늘은 이미 출근 처리되었습니다.');} if($r){$u=$pdo->prepare("UPDATE cpms_attendance_records SET check_in=:ci,status='출근중',updated_at=:u WHERE id=:id");$u->execute(array(':ci'=>$now,':u'=>$now,':id'=>$r['id']));} else {$i=$pdo->prepare("INSERT INTO cpms_attendance_records(employee_id,work_date,check_in,status,created_at,updated_at) VALUES(:e,:d,:ci,'출근중',:c,:u)");$i->execute(array(':e'=>$eid,':d'=>$today,':ci'=>$now,':c'=>$now,':u'=>$now));} $pdo->commit(); flash_set('success','출근 처리되었습니다.');}catch(Exception $e){if($pdo&&$pdo->inTransaction())$pdo->rollBack();flash_set('danger',$e->getMessage());} header('Location: ?r=대시보드');